const LINGSCOUT_LANG_NAMES = { es: "Español", ca: "Català", en: "English", fr: "Français", it: "Italiano", de: "Deutsch", pt: "Português", nl: "Nederlands", sv: "Svenska", no: "Norsk", da: "Dansk", pl: "Polski", ru: "Русский", af: "Afrikaans", ja: "日本語", zh: "中文（简体）", ko: "한국어", uk: "Українська", ary: "الدارجة المغربية", ar: "العربية", tr: "Türkçe", fa: "فارسی", he: "עברית", id: "Bahasa Indonesia", hi: "हिन्दी" };
const LINGSCOUT_LOCALES = { es: "es-ES", ca: "ca-ES", en: "en-US", fr: "fr-FR", it: "it-IT", de: "de-DE", pt: "pt-PT", nl: "nl-NL", sv: "sv-SE", no: "nb-NO", da: "da-DK", pl: "pl-PL", ru: "ru-RU", af: "af-ZA", ja: "ja-JP", zh: "zh-CN", ko: "ko-KR", uk: "uk-UA", ary: "ar-MA", ar: "ar-AE", tr: "tr-TR", fa: "fa-IR", he: "he-IL", id: "id-ID", hi: "hi-IN" };

// Idiomas que se escriben de derecha a izquierda
const LINGSCOUT_RTL = ["ar", "ary", "fa", "he"];
(function () {
  const l = localStorage.getItem('lingscout-lang') || 'es';
  document.documentElement.setAttribute('dir', LINGSCOUT_RTL.includes(l) ? 'rtl' : 'ltr');
})();

function currentLocale() {
  return LINGSCOUT_LOCALES[localStorage.getItem('lingscout-lang') || 'es'] || 'es-ES';
}

function t(key) {
  const lang = localStorage.getItem('lingscout-lang') || 'es';
  return (LINGSCOUT_TRANSLATIONS[lang] && LINGSCOUT_TRANSLATIONS[lang][key]) || LINGSCOUT_TRANSLATIONS.es[key] || key;
}

// "análisis" con la forma plural correcta (polaco y ruso tienen una forma extra para 2-4)
function pluralAnalisis(n) {
  const lang = localStorage.getItem('lingscout-lang') || 'es';
  if (lang === 'ru' || lang === 'uk') {
    const m10 = n % 10, m100 = n % 100;
    if (m10 === 1 && m100 !== 11) return t('ui.analisisUno');
    if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return t('ui.analisisPocos');
    return t('ui.analisisVarios');
  }
  if (lang === 'pl') {
    const m10 = n % 10, m100 = n % 100;
    if (n === 1) return t('ui.analisisUno');
    if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return t('ui.analisisPocos');
    return t('ui.analisisVarios');
  }
  return n === 1 ? t('ui.analisisUno') : t('ui.analisisVarios');
}

// Texto traducido del valor guardado de resistencia (termina / buena / media / mala)
function etiquetaResistencia(valor) {
  const claves = { termina: 'jf.resTermina', buena: 'jf.resBuena', media: 'jf.resMedia', mala: 'jf.resMala' };
  return claves[valor] ? t(claves[valor]) : '';
}

// Textos traducidos de los valores guardados de pie dominante y potencial
function etiquetaPie(valor) {
  const claves = { derecho: 'jf.pieDer', izquierdo: 'jf.pieIzq', ambidiestro: 'jf.pieAmbos' };
  return claves[valor] ? t(claves[valor]) : '';
}
function etiquetaPotencial(valor) {
  const claves = {
    top_mundial: 'jf.potTopMundial', top_pais: 'jf.potTopPais', superior: 'jf.potSuperior',
    poco_superior: 'jf.potPocoSuperior', igual: 'jf.potIgual', no_llega: 'jf.potNoLlega',
    liga_inferior: 'jf.potInferior', veterano: 'jf.potVeterano'
  };
  return claves[valor] ? t(claves[valor]) : '';
}

// Tendencia (con flecha) e importancia actual, a partir de los valores guardados
function etiquetaTendencia(valor) {
  const m = { mejorando: ['↗', 'jf.tendMejorando'], estancado: ['→', 'jf.tendEstancado'], bajando: ['↘', 'jf.tendBajando'] };
  return m[valor] ? m[valor][0] + ' ' + t(m[valor][1]) : '';
}
function etiquetaImportancia(valor) {
  const claves = { clave: 'jf.impClave', importante: 'jf.impImportante', rotacion: 'jf.impRotacion', secundario: 'jf.impSecundario' };
  return claves[valor] ? t(claves[valor]) : '';
}

// ---------- Acciones clave y etiquetas ----------
const LINGSCOUT_ACCIONES = ['pases_espacio', 'barridas', 'definicion', 'choque', 'regate', 'pase_filtrado', 'juego_aereo', 'presion', 'desmarque', 'centros', 'disparo_lejano', 'conduccion'];
const LINGSCOUT_TAGS_SUGERIDAS = ['regateador', 'lider', 'fragil', 'polivalente', 'fisico', 'tecnico', 'veloz', 'goleador'];

function escaparHtml(texto) {
  return String(texto).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

// Etiqueta personalizada: sin "#", sin espacios (se sustituyen por _), en minúsculas y máx. 30 caracteres
function normalizarTag(raw) {
  return String(raw).trim().replace(/^#+/, '').trim().replace(/\s+/g, '_').toLocaleLowerCase().slice(0, 30);
}

function etiquetaAccion(codigo) {
  return LINGSCOUT_ACCIONES.includes(codigo) ? t('jf.acc_' + codigo) : codigo;
}

function htmlAcciones(lista) {
  if (!lista || !lista.length) return '';
  return '<div class="chip-list">' + lista.map(c => `<span class="chip chip-accion">${escaparHtml(etiquetaAccion(c))}</span>`).join('') + '</div>';
}

function htmlTags(lista) {
  if (!lista || !lista.length) return '';
  return '<div class="chip-list">' + lista.map(x => `<span class="chip chip-tag">#${escaparHtml(normalizarTag(x))}</span>`).join('') + '</div>';
}

// Clase CSS y flecha de una tendencia guardada (mejorando / estancado / bajando)
function claseTendencia(valor) {
  return { mejorando: 'trend-up', estancado: 'trend-flat', bajando: 'trend-down' }[valor] || '';
}

// ---------- Posición ideal, salida de balón y juego de bandas/laterales ----------
const LINGSCOUT_POSICIONES = ['portero', 'central', 'lateral_der', 'lateral_izq', 'carrilero', 'pivote', 'mediocentro', 'interior', 'mediapunta', 'extremo_der', 'extremo_izq', 'delantero_centro', 'segundo_delantero'];
const LINGSCOUT_SALIDAS = ['centrales', 'laterales', 'largo_medios', 'largo_bandas', 'largo_delanteros'];

// 'adecuada' = la posición actual del jugador ya es la adecuada
function etiquetaPosicionIdeal(valor) {
  if (valor === 'adecuada') return t('jf.posAdecuada');
  return LINGSCOUT_POSICIONES.includes(valor) ? t('jf.pos_' + valor) : '';
}

// Cómo juega una banda o un lateral: por dentro / abierto / mixto / no aplicable
function etiquetaJuego(valor) {
  const claves = { dentro: 'pf.juego_dentro', abierto: 'pf.juego_abierto', mixto: 'pf.juego_mixto', na: 'pf.juego_na' };
  return claves[valor] ? t(claves[valor]) : '';
}

function htmlSalida(lista) {
  if (!lista || !lista.length) return '';
  return '<div class="chip-list">' + lista.filter(c => LINGSCOUT_SALIDAS.includes(c))
    .map(c => `<span class="chip chip-accion">${t('pf.sal_' + c)}</span>`).join('') + '</div>';
}

// Botones tipo casilla (varios a la vez). "seleccion" es un Set que se actualiza al marcar/desmarcar
function construirChipsToggle(contenedorId, codigos, prefijoClave, seleccion) {
  const cont = document.getElementById(contenedorId);
  cont.innerHTML = '';
  codigos.forEach(codigo => {
    const label = document.createElement('label');
    label.className = 'chip chip-toggle';
    const input = document.createElement('input');
    input.type = 'checkbox';
    input.value = codigo;
    input.checked = seleccion.has(codigo);
    label.classList.toggle('on', input.checked);
    input.addEventListener('change', () => {
      if (input.checked) seleccion.add(codigo); else seleccion.delete(codigo);
      label.classList.toggle('on', input.checked);
    });
    const texto = document.createElement('span');
    texto.textContent = t(prefijoClave + codigo);
    label.append(input, texto);
    cont.appendChild(label);
  });
}

// ---------- Fase defensiva: presión, marcaje y reacción ante goles ----------
function etiquetaNivel(valor) {   // altura del bloque / tipo de presión
  const c = { alta: 'pf.nivel_alta', media: 'pf.nivel_media', baja: 'pf.nivel_baja' };
  return c[valor] ? t(c[valor]) : '';
}
function etiquetaIntensidad(valor) {
  const c = { alta: 'pf.inten_alta', media: 'pf.inten_media', baja: 'pf.inten_baja' };
  return c[valor] ? t(c[valor]) : '';
}
function etiquetaCoordinacion(valor) {
  const c = { buena: 'jf.resBuena', media: 'jf.resMedia', mala: 'jf.resMala' };
  return c[valor] ? t(c[valor]) : '';
}
function etiquetaMarcaje(valor) {
  const c = { hombre: 'pf.marc_hombre', zonal: 'pf.marc_zonal', mixto: 'pf.marc_mixto' };
  return c[valor] ? t(c[valor]) : '';
}
function etiquetaReaccion(valor) {
  const c = { mantiene: 'pf.reac_mantiene', sube: 'pf.reac_sube', repliega: 'pf.reac_repliega', desordena: 'pf.reac_desordena' };
  return c[valor] ? t(c[valor]) : '';
}

function aplicarTraducciones() {
  // Si una clave no existe (por ejemplo, un i18n.js antiguo en caché), se deja el texto por defecto del HTML
  const existe = (clave) => Object.prototype.hasOwnProperty.call(LINGSCOUT_TRANSLATIONS.es, clave);
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const clave = el.getAttribute('data-i18n');
    if (existe(clave)) el.textContent = t(clave);
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const clave = el.getAttribute('data-i18n-placeholder');
    if (existe(clave)) el.setAttribute('placeholder', t(clave));
  });
  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    const clave = el.getAttribute('data-i18n-title');
    if (!existe(clave)) return;
    const txt = t(clave);
    el.setAttribute('title', txt);
    el.setAttribute('aria-label', txt);
  });
  const lang = localStorage.getItem('lingscout-lang') || 'es';
  document.documentElement.setAttribute('lang', LINGSCOUT_LOCALES[lang] || lang);
  document.documentElement.setAttribute('dir', LINGSCOUT_RTL.includes(lang) ? 'rtl' : 'ltr');
}

document.addEventListener('DOMContentLoaded', () => {
  aplicarTraducciones();
  const actual = localStorage.getItem('lingscout-lang') || 'es';
  document.querySelectorAll('.lang-selector').forEach(selector => {
    selector.value = actual;
    selector.addEventListener('change', () => {
      localStorage.setItem('lingscout-lang', selector.value);
      location.reload();
    });
  });
});
